import type { InlineGraphic } from "@/lib/coachSite/graphics";

/**
 * Draws a print-pack graphic inline, so it stays sharp at any size and uses the
 * page's fonts. The markup is generated by our own print-pack code from app data
 * (area names, playbooks, the coach's name escaped), never from visitor input.
 */
export function Graphic({ graphic, className }: { graphic: InlineGraphic; className?: string }) {
  return (
    <svg
      className={className}
      viewBox={graphic.viewBox}
      role="img"
      aria-label={graphic.title}
      xmlns="http://www.w3.org/2000/svg"
      dangerouslySetInnerHTML={{ __html: graphic.body }}
    />
  );
}
